package com.dentalcrm.service;
import com.dentalcrm.appointment.AppointmentServiceItem; import org.junit.jupiter.api.*; import java.math.BigDecimal; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class ClinicServiceManagerTest {private ClinicServiceRepository repo;private ClinicServiceManager manager;private ClinicService service;
 @BeforeEach void setup(){repo=mock(ClinicServiceRepository.class);manager=new ClinicServiceManager(repo);service=new ClinicService();service.setId(1L);service.setName("Лечение");service.setPrice(new BigDecimal("1000"));service.setDurationMinutes(30);service.setActive(true);when(repo.findById(1L)).thenReturn(Optional.of(service));when(repo.save(any())).thenAnswer(i->{ClinicService s=i.getArgument(0);s.setId(2L);return s;});}
 @Test void createsValidService(){var result=manager.create(new ServiceDtos.ServiceRequest("Осмотр",BigDecimal.ZERO,15,true));assertEquals(BigDecimal.ZERO,result.price());assertEquals(15,result.durationMinutes());}
 @Test void priceUpdateDoesNotChangeHistoricalSnapshot(){AppointmentServiceItem historical=new AppointmentServiceItem();historical.setPrice(new BigDecimal("1000"));historical.setQuantity(2);manager.update(1L,new ServiceDtos.ServiceRequest("Лечение",new BigDecimal("1500"),30,true));assertEquals(new BigDecimal("1500"),service.getPrice());assertEquals(new BigDecimal("2000"),historical.lineTotal());}
 @Test void deactivationPreservesServiceAndExcludesItFromActiveQuery(){manager.update(1L,new ServiceDtos.ServiceRequest("Лечение",service.getPrice(),30,false));assertFalse(service.isActive());verify(repo,never()).delete(any());when(repo.findByActiveTrueOrderByName()).thenReturn(java.util.List.of());assertTrue(manager.all(true).isEmpty());}
}
